@container (max-width: 900px) {
  .fd-required-fields {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fd-connect-panel {
    padding: 28px;
  }
}
@container (max-width: 570px) {
  .fd-connect-panel {
    padding: 20px 13px;
  }
  .fd-connect-panel h2 {
    font-size: 21px;
  }
  .fd-required-fields {
    gap: 6px;
  }
  .fd-required-fields > span {
    padding: 8px 6px;
    font-size: 9px;
  }
}
/* Workforce extensions to the Finance OS design system. */
.wo-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}
.wo-grid > .fd-panel {
  margin-bottom: 0;
}
.wo-composition {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding: 15px 0;
}
.wo-composition > div {
  display: flex;
  align-items: center;
  gap: 12px;
}
.wo-composition i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.wo-composition strong {
  font-size: 27px;
  width: 90px;
}
.wo-composition span {
  color: var(--fd-muted);
  flex: 1;
}
.wo-composition b {
  font-weight: 500;
}
.wo-note {
  font-size: 10px;
  color: var(--fd-muted);
  padding: 16px 0;
}
.wo-signals {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 25px;
  padding: 10px 0;
}
.wo-signals p {
  font-size: 11px;
  color: var(--fd-muted);
}
.wo-signals strong {
  display: block;
  font-size: 25px;
  color: var(--fd-text);
  margin-bottom: 7px;
}
.wo-org {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  padding: 15px 0;
}
.wo-person {
  width: 220px;
  background: var(--fd-soft);
  color: var(--fd-text);
  border: 1px solid var(--fd-line);
  border-top: 3px solid #2768ed;
  border-radius: 10px;
  padding: 20px 14px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 8px;
  text-align: center;
}
.wo-person > span:not(.fd-avatar) {
  font-size: 10px;
  color: var(--fd-muted);
  min-height: 28px;
}
.wo-person > div {
  display: flex;
  gap: 18px;
  padding: 10px 0;
}
.wo-person small {
  display: block;
  font-size: 8px;
  font-weight: 400;
  color: var(--fd-muted);
}
.wo-person em {
  font-size: 10px;
  font-style: normal;
  color: #2768ed;
  padding-top: 10px;
}
.wo-org-actions {
  display: flex;
  gap: 15px;
  align-items: center;
  padding: 12px 0;
  font-size: 11px;
}
.wo-org-actions button {
  border: 1px solid var(--fd-line);
  padding: 6px 12px;
  border-radius: 5px;
  background: var(--fd-soft);
  color: var(--fd-text);
}
.wo-search {
  width: 320px;
  max-width: 100%;
  padding: 10px;
  border: 1px solid var(--fd-line);
  border-radius: 6px;
  background: var(--fd-soft);
  color: var(--fd-text);
  margin-bottom: 15px;
}
.wo-table {
  overflow: auto;
}
.wo-table table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
  text-align: left;
}
.wo-table td,
.wo-table th {
  padding: 12px;
  border-bottom: 1px solid var(--fd-line);
  white-space: nowrap;
}
.wo-table th {
  color: var(--fd-muted);
  font-size: 10px;
  font-weight: 500;
}
.wo-table small {
  display: block;
  color: var(--fd-muted);
  font-size: 9px;
}
.wo-footer {
  font-size: 9px;
  color: var(--fd-muted);
  display: flex;
  justify-content: space-between;
  padding: 20px 0;
}
.wo-demo {
  height: 28px;
  background: #fff2d4;
  color: #765811;
  font: 11px/28px 'Segoe UI', sans-serif;
  text-align: center;
  letter-spacing: 0.7px;
}
.fd-filterbar {
  flex-wrap: wrap;
}
.fd-kpi-icon {
  font-size: 24px;
}
.fd-main {
  padding-top: 25px;
}
.fd-two-grid {
  margin-bottom: 22px;
}
.fd-panel p {
  line-height: 1.7;
}
@media (max-width: 950px) {
  .fd-sidebar {
    width: 180px;
  }
  .wo-grid,
  .fd-two-grid {
    grid-template-columns: 1fr;
  }
  .fd-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 28px;
  }
  .wo-signals {
    grid-template-columns: repeat(2, 1fr);
  }
}
.finance-dashboard .fd-bar-row:disabled {
  opacity: 1;
}
